def get_batch_no_from_bundle(bundle):
    if not bundle:
        return None

    return frappe.db.get_value(
        "Serial and Batch Entry",
        {"parent": bundle},
        "batch_no"
    )

created = False

for item in doc.items:

    target_warehouse = item.t_warehouse or doc.to_warehouse

    frappe.log_error(
        f"Checking item {item.item_code} | Warehouse: {target_warehouse}",
        "QC TRACE"
    )

    if not target_warehouse or target_warehouse not in QC_WAREHOUSES:
        continue

    has_batch = frappe.db.get_value("Item", item.item_code, "has_batch_no")
    if not has_batch:
        continue

    batch_no = item.batch_no or get_batch_no_from_bundle(item.serial_and_batch_bundle)

    if not batch_no:
        frappe.throw(
            f"Batch No is mandatory for Quality Inspection. "
            f"Please set Batch No for Item <b>{item.item_code}</b>"
        )

    if frappe.db.exists(
        "Quality Inspection",
        {
            "reference_type": "Stock Entry",
            "reference_name": doc.name,
            "item_code": item.item_code,
            "batch_no": batch_no,
        }
    ):
        continue

    qi = frappe.get_doc({
        "doctype": "Quality Inspection",
        "inspection_type": "Incoming",
        "reference_type": "Stock Entry",
        "reference_name": doc.name,
        "item_code": item.item_code,
        "batch_no": batch_no,
        "sample_size": 1,
        "company": doc.company,
        "custom_inspection_for":"RM",
        "inspected_by": frappe.session.user,
    })

    qi.insert(ignore_permissions=True)
    created = True

if not created:
