def get_section(warehouse):
    if "(A)" in warehouse:
        return "A"
    if "(B)" in warehouse:
        return "B"
    if "(C)" in warehouse:
        return "C"
    return None


def get_store_type(warehouse):
    if "Receiving Store" in warehouse:
        return "RECEIVING"
    if "Under Test Store" in warehouse:
        return "UNDER_TEST"
    if "Approved Store" in warehouse:
        return "APPROVED"
    if "Reject Store" in warehouse:
        return "REJECT"
    if "Work In Progress" in warehouse:
        return "WIP"
    return None


def get_material_type(warehouse):
    if "RM" in warehouse:
        return "RM"
    if "PM" in warehouse:
        return "PM"
    return None


for row in doc.items:

    from_wh = row.s_warehouse or doc.from_warehouse
    to_wh = row.t_warehouse or doc.to_warehouse

    if not from_wh or not to_wh:
        continue

    from_section = get_section(from_wh)
    to_section = get_section(to_wh)

    if from_section != to_section:
        frappe.throw(f"Section mismatch not allowed: {from_wh} → {to_wh}")

    from_type = get_store_type(from_wh)
    to_type = get_store_type(to_wh)

    material_type = get_material_type(from_wh)

    # =========================
    # RECEIVING → UNDER TEST
    # =========================
    if from_type == "RECEIVING":
        if to_type != "UNDER_TEST":
            frappe.throw("Receiving Store can move only to Under Test Store")

    # =========================
    # UNDER TEST → APPROVED / REJECT
    # =========================
    elif from_type == "UNDER_TEST":
        if to_type not in ["APPROVED", "REJECT"]:
            frappe.throw("Under Test Store can move only to Approved or Reject Store")

    # =========================
    # REJECT → UNDER TEST / RECEIVING
    # =========================
    elif from_type == "REJECT":
        if to_type not in ["UNDER_TEST", "RECEIVING"]:
            frappe.throw("Reject Store can move only to Under Test or Receiving")

    # =========================
    # APPROVED → ANY SAME MATERIAL TYPE STORE IN SAME SECTION
    # =========================
    elif from_type == "APPROVED":
        if material_type and material_type not in to_wh:
            frappe.throw("Approved Store can move only to same material type store in same section")

    # =========================
    # WIP → APPROVED (Same Section)
    # =========================
    elif from_type == "WIP":
        if to_type != "APPROVED":
            frappe.throw("WIP can move only to Approved Store")

if doc.stock_entry_type == "Material Transfer":

    requires_approval = False

    for item in doc.items:

        if (
            item.s_warehouse
            and item.t_warehouse
            and "Reject" in item.s_warehouse
            and "Under Test" in item.t_warehouse
