# BLOCK FG SUBMIT if Semi-FG not produced

if doc.custom_product_type == "Finished":

    if not doc.custom_manufacturing_batch:
        frappe.throw("Manufacturing Batch not linked")

    batch = frappe.get_doc(
        "Manufacturing Batch",
        doc.custom_manufacturing_batch
    )

    if not batch:
        frappe.throw("Manufacturing Batch not found")

    # Block if Semi-FG not produced
    if not batch.semi_fg_completed:
        frappe.throw(
            f"Cannot Submit FG Work Order.\nFirst produce Semi-FG for batch {batch.semi_fg_batch}"
        )

    if batch.fg_completed:
        frappe.throw(
            f"Batch already completed.\nCannot reuse batch {batch.batch_number}"
        )    
    # lock if insufficient Semi-FG qty
    if float(batch.semi_fg_qty or 0) < float(doc.qty or 0):
        frappe.throw(
            f"Not enough Semi-FG available.\nBatch: {batch.semi_fg_batch}\nAvailable: {batch.semi_fg_qty}\nRequired: {doc.qty}"
        )


    available_qty = float(batch.semi_fg_qty or 0) - float(batch.custom_fg_produced_quantity or 0)
    required_qty = float(doc.qty or 0)

    # Block if insufficient in SAME batch
    if available_qty < required_qty:
        frappe.throw(
            f"Not enough Semi-FG in selected batch.\n"
            f"Batch: {batch.batch_number}\n"
            f"Available: {available_qty}\n"
            f"Required: {required_qty}"
        )

if doc.stock_entry_type == "Manufacture":

    for item in doc.items:

        if item.is_finished_item and item.batch_no:

            if doc.custom_manufacturing_batch:

                batch = frappe.get_doc(
                    "Manufacturing Batch",
                    doc.custom_manufacturing_batch
                )

                if item.item_code == batch.semi_finished_item \
                   and item.batch_no == batch.semi_fg_batch:

                    #batch.semi_fg_qty = (batch.semi_fg_qty or 0) - item.qty
                    batch.semi_fg_qty = float(batch.semi_fg_qty or 0) - float(item.qty or 0)

                    if float(batch.semi_fg_qty) <= 0:
                        batch.semi_fg_completed = 0

